contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount, uint8 reentrancyDepth) public {
        // Bound to admissible domain: deposit up to a reasonable amount, withdraw within deposited balance
        vm.assume(depositAmount > 0 && depositAmount <= 1000 ether);
        vm.assume(withdrawAmount > 0 && withdrawAmount <= depositAmount);
        // Reentrancy depth limits the number of re-entrant calls the attacker will attempt
        vm.assume(reentrancyDepth >= 1 && reentrancyDepth <= 5);

        // Deploy a minimal reentrant attacker helper contract that embodies the adversarial behavior
        Attacker attacker = new Attacker(c, withdrawAmount, reentrancyDepth);
        address attackerAddr = address(attacker);

        // Fund attacker's deposit
        vm.deal(attackerAddr, depositAmount);
        vm.startPrank(attackerAddr);

        // Attacker deposits into the contract
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = c.balances(attackerAddr);

        // Attacker calls withdraw, triggering the reentrancy loop
        attacker.attack();

        vm.stopPrank();

        // After withdrawal, the attacker's balance must be correctly reduced
        // In reference: balanceAfter = balanceBefore - withdrawAmount
        // In buggy: reentrancy can drain more, breaking the invariant
        uint256 balanceAfter = c.balances(attackerAddr);
        assertTrue(balanceAfter == balanceBefore - withdrawAmount);
    }
}

